INSERT OR REPLACE INTO "Announcement" ("id", "title", "slug", "content", "targetRoles", "isPinned", "createdAt") VALUES ('ae8f5179-3ffe-4403-af91-8930d94b904b', 'Welcome to Academic Year 2026/2027 Semester I Course Registration', 'welcome-academic-year-2026-2027-registration', 'The Office of the Registrar announces that regular online course registration for Semester I is officially open. All health science students must confirm their pre-matched curriculum courses and obtain clearance from the registrar before October 31, 2026.', 'STUDENT,REGISTRAR', 1, '2026-10-25T12:56:50.797Z');
INSERT OR REPLACE INTO "Announcement" ("id", "title", "slug", "content", "targetRoles", "isPinned", "createdAt") VALUES ('9a5ab868-a64f-4bb3-b115-4abc52b66eca', 'Continuous Assessment & Midterm Submission Schedule for Instructors', 'continuous-assessment-submission-schedule', 'All academic staff are reminded that Continuous Assessment grades (comprising 50% of the overall evaluation) must be submitted via the Teacher Portal Grade Sheet Engine by the end of Week 10.', 'TEACHER,ADMIN', 1, '2026-10-25T12:56:50.809Z');
INSERT OR REPLACE INTO "Announcement" ("id", "title", "slug", "content", "targetRoles", "isPinned", "createdAt") VALUES ('d37f8f2b-53ce-4a41-a9b1-a46942ad9ca6', 'Clinical Attachment Orientation at Tikur Anbessa Specialized Hospital', 'clinical-attachment-orientation', 'Second and Third Year Nursing and Public Health students assigned to clinical attachments must attend the mandatory infection prevention and clinical protocol orientation this Friday in Auditorium B.', 'STUDENT,TEACHER', 0, '2026-10-25T12:56:50.817Z');
